not scan their descendants for mask classes; the portal is\n      // only probed through its own direct children.\n      if (!settingsStateChanged && appNodes.length > 0 && target !== undefined\n        && (target.closest(SETTINGS_OWNER_SELECTOR) !== null\n          || (target === body && appNodes.some(node => (node as Element)\n            .querySelector(`:scope > ${SETTINGS_PORTAL_DIALOG_SELECTOR}`) !== null)))) {\n        settingsStateChanged = true\n      }\n      if (!projectedStateChanged && appNodes.length > 0 && (appNodes.some(node => nodeTouches(node, PROJECTED_STATE_SELECTOR))\n        || target?.matches(\"header, [data-slot='main'], [data-slot='sidebar.settings']\") === true)) {\n        projectedStateChanged = true\n      }\n    }\n    if (rootLayoutChanged) syncShellKind()\n    if (projectedStateChanged || settingsStateChanged) syncProjectedState()\n    if (!sidebarStructureChanged && settingsStateChanged) syncSidebarCarriers()\n    if (sidebarStructureChanged) syncSidebarDecorations()\n    else if (workspaceStateChanged) decorateWorkspaceTree(decoratedElements)\n    if (!sidebarStructureChanged && chatStructureChanged) {\n      ensureChatAreaStage(characterStage)\n      ensureChatAreaChrome(topTrim, bottomTrim)\n      ensureResizeObserved()\n    }\n    if (backdropChanged) syncBackdrop()\n    if (composerChanged) {\n      ensureComposerLaceRail(composerLaceRail)\n      syncComposerMotion()\n    }\n    if (settingsStateChanged || projectedStateChanged) syncSettingsBackdropFrame()\n  })\n  observer.observe(body, {\n    attributes: true,\n    attributeFilter: [\n      'aria-expanded',\n      'aria-selected',\n      'data-cordis-panel',\n      'data-ds-dark-theme',\n      'data-phase',\n      'data-slot',\n      'role',\n    ],\n    childList: true,\n    subtree: true,\n  })\n\n  syncSidebarCarriers()\n  installMaidPageIcons(ctx)\n  installMaidPlatformCaption(ctx, body)\n\n  document.title = SKIN_TITLE\n}\n"
