    {
      "path": "maid-atelier/src/client/customization.ts",
      "content": "import {\n  exposeSkinCustomization,\n  SKIN_CUSTOMIZATION_PROTOCOL,\n  SkinAttributeProjector,\n  type SkinCustomizationState,\n  type SkinSettingValue,\n} from '../../../skin-manager/src/protocol.ts'\n\nconst ATTR_ART = 'data-dsh-whale-maid-art'\nconst ATTR_FONT = 'data-dsh-whale-maid-font'\nconst ATTR_WORKSPACE_FONT = 'data-dsh-whale-maid-workspace-font'\nconst ATTR_MODEL_EXIT = 'data-dsh-whale-maid-model-exit'\nconst ATTR_MODEL = 'data-dsh-whale-model'\nconst ATTR_FLASH_GLASSES = 'data-dsh-whale-maid-flash-glasses'\nconst ATTR_COMPOSER_MODE = 'data-maid-composer-mode'\nconst ATTR_COMPOSER_BOTTOM_ONLY = 'data-maid-composer-bottom-only'\nconst ATTR_NAV_MODE = 'data-maid-nav-mode'\n/** Navigation layouts the stylesheet implements; anything else falls back to the default. */\nconst NAV_MODES = new Set(['corner', 'topbar', 'rail'])\n\nconst WORKSPACE_FONTS = new Set(['serif', 'system', 'conversation'])\n\n// Keep the original banner height unless the user chooses a compact layout.\nconst WORKSPACE_ROW_HEIGHT_DEFAULT = 54\nconst WORKSPACE_ROW_HEIGHT_MIN = 22\nconst WORKSPACE_ROW_HEIGHT_MAX = 54\nconst WORKSPACE_ROW_HEIGHT_PROPERTY = '--maid-workspace-row-height'\n\n/** Restore the original inline value and priority only while this writer owns it. */\nclass SkinPropertyProjector {\n  private readonly originals = new Map<string, { value: string, priority: string }>()\n  private readonly owned = new Map<string, string>()\n\n  constructor(private readonly root: HTMLElement = document.documentElement) {}\n\n  set(name: string, value: string): void {\n    if (!this.originals.has(name)) {\n      this.originals.set(name, {\n        value: this.root.style.getPropertyValue(name),\n        priority: this.root.style.getPropertyPriority(name),\n      })\n    }\n    this.root.style.setProperty(name, value)\n    this.owned.set(name, value)\n  }\n\n  release(): void {\n    for (const [name, original] of this.originals) {\n      if (this.root.style.getPropertyValue(name) === this.owned.get(name)\n        && this.root.style.getPropertyPriority(name) === '') {\n        if (original.value === '') this.root.style.removeProperty(name)\n        else this.root.style.setProperty(name, original.value, original.priority)\n      }\n    }\n    this.originals.clear()\n    this.owned.clear()\n  }\n}\n\nfunction workspaceRowHeight(value: SkinSettingValue | undefined): number {\n  if (typeof value !== 'number' || !Number.isFinite(value)) return WORKSPACE_ROW_HEIGHT_DEFAULT\n  return Math.min(WORKSPACE_ROW_HEIGHT_MAX, Math.max(WORKSPACE_ROW_HEIGHT_MIN, Math.round(value)))\n}\n\n/**\n * The lineup is DeepSeek Flash and DeepSeek Pro, so the display name only\n * decides which side the artwork sits on. Both families carry vision now: the\n * glasses artwork is a separate switch (`flashGlasses`) instead of a `vision`\n * substring match, which used to split an older V4 name into a third family.\n */\nexport function modelFamily(name: string): 'pro' | 'flash' | null {\n  const compact = name.toLowerCase().replace(/[^a-z0-9]/g, '')\n  if (!compact.includes('deepseek')) return null\n  if (compact.includes('pro')) return 'pro'\n  if (compact.includes('flash')) return 'flash'\n  return null\n}\n\n/** Expose controls and keep every resulting DOM mutation skin-owned. */\nexport function installMaidCustomization(root: HTMLElement = document.documentElement): () => void {\n  const projector = new SkinAttributeProjector(root)\n  const properties = new SkinPropertyProjector(root)\n  let observer: MutationObserver | undefined\n  let frame: number | undefined\n  let activeState: SkinCustomizationState | null = null\n  let mobile = window.innerWidth <= 700\n\n  const synchronizeModel = (): void => {\n    let family: ReturnType<typeof modelFamily> = null\n    for (const trigger of document.querySelectorAll<HTMLElement>(\"[data-composer-card] button[aria-haspopup='menu']\")) {\n      family = modelFamily(`${trigger.title} ${trigger.getAttribute('aria-label') ?? ''} ${trigger.textContent ?? ''}`)\n      if (family !== null) break\n    }\n    if (family === null) projector.unset(ATTR_MODEL)\n    else projector.set(ATTR_MODEL, family)\n  }\n\n  const scheduleModelSync = (): void => {\n    if (frame !== undefined) return\n    frame = requestAnimationFrame(() => {\n      frame = undefined\n      synchronizeModel()\n    })\n  }\n\n  const startModelObserver = (): void => {\n    if (observer !== undefined) return\n    observer = new MutationObserver(records => {\n      if (records.some(record => {\n        const element = record.target instanceof Element ? record.target : undefined\n        if (record.type === 'childList' && element?.closest('[data-composer-input]')) return false\n        if (record.type === 'attributes') return element?.matches(\"button[aria-haspopup='menu']\") === true\n        if (element?.closest(\"[data-composer-card] button[aria-haspopup='menu']\")) return true\n        return [...record.addedNodes, ...record.removedNodes].some(node => (\n          node instanceof Element\n          && (node.matches(\"[data-composer-card], button[aria-haspopup='menu']\")\n            || node.querySelector(\"[data-composer-card], button[aria-haspopup='menu']\"))\n        ))\n      })) scheduleModelSync()\n    })\n    observer.observe(document.body, {\n      attributes: true,\n      attributeFilter: ['aria-label', 'title'],\n      childList: true,\n      subtree: true,\n    })\n    synchronizeModel()\n  }\n\n  const stopModelObserver = (): void => {\n    observer?.disconnect()\n    observer = undefined\n    if (frame !== undefined) cancelAnimationFrame(frame)\n    frame = undefined\n    projector.release(ATTR_MODEL)\n  }\n\n  const synchronizeModelMode = (): void => {\n    if (activeState === null) return\n    const modelExit = mobile\n      ? activeState.values.mobileModelExit !== false\n      : activeState.values.modelExit === true\n    projector.set(ATTR_MODEL_EXIT, modelExit ? 'enabled' : 'disabled')\n    if (modelExit) startModelObserver()\n    else stopModelObserver()\n  }\n\n  const onResize = (): void => {\n    const nextMobile = window.innerWidth <= 700\n    if (mobile === nextMobile) return\n    mobile = nextMobile\n    synchronizeModelMode()\n  }\n\n  const apply = (state: SkinCustomizationState | null): void => {\n    if (state === null) {\n      window.removeEventListener('resize', onResize)\n      activeState = null\n      stopModelObserver()\n      projector.release()\n      properties.release()\n      return\n    }\n    if (activeState === null) window.addEventListener('resize', onResize)\n    activeState = state\n    mobile = window.innerWidth <= 700\n    const artwork = state.values.artwork === true\n    const scheduleVisible = state.visibility.sfwMode !== false\n    projector.set(ATTR_ART, artwork && scheduleVisible ? 'visible' : 'hidden')\n    projector.set(ATTR_FONT, state.values.font === 'serif' ? 'serif' : 'system')\n    const workspaceFont = state.values.workspaceFont\n    projector.set(ATTR_WORKSPACE_FONT, typeof workspaceFont === 'string' && WORKSPACE_FONTS.has(workspaceFont) ? workspaceFont : 'serif')\n    projector.set(ATTR_FLASH_GLASSES, state.values.flashGlasses === true ? 'on' : 'off')\n    synchronizeModelMode()\n    projector.set(ATTR_COMPOSER_MODE, typeof state.values.composerMode === 'string' ? state.values.composerMode : 'persistent')\n    projector.set(ATTR_COMPOSER_BOTTOM_ONLY, state.values.composerBottomOnly === true ? 'on' : 'off')\n    const navMode = state.values.mobileNav\n    projector.set(ATTR_NAV_MODE, typeof navMode === 'string' && NAV_MODES.has(navMode) ? navMode : 'corner')\n    properties.set(WORKSPACE_ROW_HEIGHT_PROPERTY, `${workspaceRowHeight(state.values.workspaceRowHeight)}px`)\n  }\n\n  return exposeSkinCustomization({\n    protocol: SKIN_CUSTOMIZATION_PROTOCOL,\n    skinId: 'maid-atelier',\n    title: '深海女仆工坊',\n    titleEn: 'Abyssal Maid Atelier',\n    settings: [\n      {\n        key: 'artwork',\n        type: 'boolean',\n        label: '显示双女仆立绘',\n        labelEn: 'Show the twin maid artwork',\n        defaultValue: true,\n      },\n      {\n        key: 'sfwMode',\n        type: 'visibility-schedule',\n        label: '不那么二次元模式',\n        labelEn: 'Not-so-anime mode',\n        description: '按本机时间控制大幅立绘；可设置工作时段隐藏、其他时间显示，也可反向设置。',\n        descriptionEn: 'Control the large artwork by local time; hide it during work hours and show it otherwise, or the reverse.',\n        defaultValue: { enabled: false, outside: 'visible', ranges: [] },\n      },\n      {\n        key: 'font',\n        type: 'select',\n        label: '对话区字体',\n        labelEn: 'Conversation font',\n        defaultValue: 'system',\n        options: [\n          { value: 'system', label: '系统默认无衬线', labelEn: 'System default sans' },\n          { value: 'serif', label: 'Georgia 衬线（#22）', labelEn: 'Georgia serif (#22)' },\n        ],\n      },\n      {\n        key: 'workspaceFont',\n        type: 'select',\n        label: '侧栏字体',\n        labelEn: 'Sidebar font',\n        description: '调整侧栏中工作区和会话标签的字体。',\n        descriptionEn: 'Font for workspace and conversation labels in the sidebar.',\n        defaultValue: 'serif',\n        options: [\n          { value: 'serif', label: 'Georgia 衬线（皮肤默认）', labelEn: 'Georgia serif (skin default)' },\n          { value: 'system', label: '系统默认无衬线', labelEn: 'System default sans' },\n          { value: 'conversation', label: '跟随对话区字体', labelEn: 'Follow the conversation font' },\n        ],\n      },\n      {\n        key: 'modelExit',\n        type: 'boolean',\n        label: '桌面端根据所选模型显示立绘',\n        labelEn: 'Show artwork based on the selected model on desktop',\n        defaultValue: false,\n      },\n      {\n        key: 'mobileModelExit',\n        type: 'boolean',\n        label: '移动端根据所选模型显示立绘',\n        labelEn: 'Show artwork based on the selected model on mobile',\n        defaultValue: true,\n      },\n      {\n        key: 'flashGlasses',\n        type: 'boolean',\n        label: 'flash🧐 带眼镜立绘',\n        labelEn: 'flash 🧐 glasses artwork',\n        description: 'flash 模型改用带眼镜的立绘。',\n        descriptionEn: 'Use the glasses artwork for the flash model.',\n        defaultValue: false,\n        visibleWhen: {\n          // The top-level single-key form is what a manager that predates\n          // `anyOf` reads; it lands on the mobile switch (on by default), so\n          // the control still renders there instead of throwing on an absent\n          // `values`.\n          key: 'mobileModelExit',\n          values: [true],\n          anyOf: [\n            { key: 'modelExit', values: [true] },\n            { key: 'mobileModelExit', values: [true] },\n          ],\n        },\n      },\n      {\n        key: 'mobileNav',\n        type: 'select',\n        label: '移动端导航方式',\n        labelEn: 'Phone navigation layout',\n        description: '仅影响竖屏手机（宽度 ≤700px）：左上角品牌图标（默认）、横向顶栏，或宿主原本的纵向侧栏。桌面与横屏不受影响。',\n        descriptionEn: 'Portrait phones only (≤700px wide): a brand mark in the top-left corner (default), a horizontal top bar, or the host\\u2019s own vertical column. Desktop and landscape are untouched.',\n        defaultValue: 'corner',\n        options: [\n          { value: 'corner', label: '左上角品牌图标', labelEn: 'Brand mark · top-left corner' },\n          { value: 'topbar', label: '横向顶栏', labelEn: 'Horizontal top bar' },\n          { value: 'rail', label: '纵向侧栏（宿主默认）', labelEn: 'Vertical column (host default)' },\n        ],\n      },\n      {\n        key: 'composerMode',\n        type: 'select',\n        label: '输入框显示方式',\n        labelEn: 'Composer visibility mode',\n        description: '始终显示；空态胶囊在输入框为空且未聚焦时收起为简约胶囊；滚动显隐在正文末尾滚出视口后上滚隐去，下滚或末尾回到视口时渐现。',\n        descriptionEn: 'Always visible; the idle capsule collapses while empty and unfocused; scroll mode hides on upward scroll after the transcript tail leaves the viewport, and reveals on downward scroll or when the tail returns.',\n        defaultValue: 'persistent',\n        options: [\n          { value: 'persistent', label: '始终显示', labelEn: 'Always visible' },\n          { value: 'capsule', label: '空态胶囊（点击展开）', labelEn: 'Idle capsule (click to expand)' },\n          { value: 'scroll', label: '上滚隐去 · 下滚渐现', labelEn: 'Hide on scroll up · show on scroll down' },\n        ],\n      },\n      {\n        key: 'composerBottomOnly',\n        type: 'boolean',\n        label: '输入框只在底部显示',\n        labelEn: 'Show the composer only at the conversation bottom',\n        description: '最新正文末尾仍在视口内时保留输入框，末尾滚出视口后隐去，回到视口内再显现。开启后接管上面的「上滚隐去 · 下滚渐现」。',\n        descriptionEn: 'Keep the composer while the transcript tail is within the viewport; hide after it leaves and reveal when it returns. Takes over the scroll mode above.',\n        defaultValue: false,\n      },\n      {\n        key: 'workspaceRowHeight',\n        type: 'range',\n        control: 'stepper',\n        label: '工作区横幅高度',\n        labelEn: 'Workspace banner height',\n        description: '仅影响工作区标签，不影响会话标签。',\n        descriptionEn: 'Only affects workspace labels, not conversation labels.',\n        defaultValue: WORKSPACE_ROW_HEIGHT_DEFAULT,\n        min: WORKSPACE_ROW_HEIGHT_MIN,\n        max: WORKSPACE_ROW_HEIGHT_MAX,\n        step: 1,\n        unit: 'px',\n      },\n    ],\n    apply,\n  })\n}\n"
    },
    {
      "path": "maid-atelier/src/client/page-icons.ts",
      "content": "import type { Context } from '@deepseek-ai/cordis'\nimport { SLEEPY_32, DELIGHTED_32, DETERMINED_32, DELIGHTED_192, DELIGHTED_512 } from './icon-art.generated.ts'\n\n// Module lifetime keeps the choice stable across skin toggles within this page.\nconst PAGE_ICON = [SLEEPY_32, DELIGHTED_32, DETERMINED_32][Math.floor(Math.random() * 3)]!\nconst installations = new WeakMap<Document, { users: number, restore: () => void }>()\n\nexport function installMaidPageIcons(ctx: Context): void {\n  ctx.effect(() => {\n    const doc = document\n    let installation = installations.get(doc)\n    if (installation === undefined) {\n      installation = { users: 0, restore: mountPageIcons(doc) }\n      installations.set(doc, installation)\n    }\n    const current = installation\n    current.users += 1\n    let active = true\n    return () => {\n      if (!active) return\n      active = false\n      if (--current.users > 0) return\n      current.restore()\n      installations.delete(doc)\n    }\n  }, 'ui-skin-maid-atelier: page icons')\n}\n\nfunction mountPageIcons(doc: Document): () => void {\n  const replaced: Array<{ node: HTMLLinkElement; anchor: Comment }> = []\n  const owned: HTMLLinkElement[] = []\n  const restore = (): void => {\n    for (const node of owned) node.remove()\n    for (const { node, anchor } of replaced) {\n      if (anchor.parentNode !== null && !node.isConnected) anchor.replaceWith(node)\n      else anchor.remove()\n    }\n  }\n\n  try {\n    // Preserve exact positions and attributes, including adjacent host links.\n    for (const node of doc.head.querySelectorAll<HTMLLinkElement>('link[rel~=\"icon\"], link[rel=\"manifest\"]')) {\n      const anchor = doc.createComment('maid-atelier: host icon')\n      replaced.push({ node, anchor })\n      node.before(anchor)\n      node.remove()\n    }\n\n    const append = (rel: string, href: string, type: string): HTMLLinkElement => {\n      const node = doc.createElement('link')\n      owned.push(node)\n      node.rel = rel\n      node.href = href\n      node.type = type\n      node.dataset.skinChrome = rel === 'icon' ? 'favicon' : 'manifest'\n      node.dataset.skinOwner = 'maid-atelier'\n      doc.head.append(node)\n      return node\n    }\n    append('icon', PAGE_ICON, 'image/png').setAttribute('sizes', '32x32')\n\n    // Official DSH apps/web/public/manifest.webmanifest fields; data manifests\n    // need absolute URLs to preserve the application's identity and scope.\n    const root = new URL('/', doc.location.href).href\n    const manifest = {\n      id: root,\n      name: 'DeepSeek Harness',\n      short_name: 'DSH',\n      start_url: root,\n      scope: root,\n      display: 'fullscreen',\n      icons: [\n        { src: DELIGHTED_192, sizes: '192x192', type: 'image/png', purpose: 'any' },\n        { src: DELIGHTED_512, sizes: '512x512', type: 'image/png', purpose: 'any' },\n      ],\n    }\n    append('manifest', `data:application/manifest+json,${encodeURIComponent(JSON.stringify(manifest))}`, 'application/manifest+json')\n  } catch (error) {\n    restore()\n    throw error\n  }\n  return restore\n}\n"
    },
    {
      "path": "maid-atelier/src/client/table-card.ts",
      "content": "/**\n * DSH wide-markdown-table preview/expand treatment.\n *\n * The official renderer marks >=4-column tables with the bare `md-table-wide`\n * hook and expands them out of the message column. In the maid bubble that\n * makes tables readable, but the sudden white slab competes with the chat\n * rhythm. This module keeps the table embedded by default, marks genuinely\n * overflowing tables as expandable, and opens a skin-owned enlarged clone on\n * explicit user intent. The renderer owns the original table subtree, so the\n * enhancer decorates that wrapper in place and never reparents it. The\n * renderer's column-count hook is only a discovery hint: activation follows\n * the live table and bubble geometry instead.\n *\n * Every observer, listener, injected button, overlay, and attribute write is\n * owned here and released by the returned disposer: application order, hot\n * switching, and partial failures cannot leave a wrapper decorated.\n */\nimport type { Context } from '@deepseek-ai/cordis'\n\nexport const MAID_TABLE_SELECTOR = '.md-table-wide'\nconst SKIN_OWNER = 'maid-atelier'\nconst EXPANDABLE_ATTRIBUTE = 'data-maid-table-expandable'\nconst OPEN_ATTRIBUTE = 'data-maid-table-open'\nconst CONTROL_ATTRIBUTE = 'data-maid-table-expand'\nconst FRAME_ATTRIBUTE = 'data-maid-table-frame'\nconst SCROLL_SUPPRESSED_ATTRIBUTE = 'data-maid-table-scroll-suppressed'\nconst OVERLAY_ATTRIBUTE = 'data-maid-table-lightbox'\nconst MODAL_DIALOG_SELECTOR = \"[role='dialog'][aria-modal='true']\"\nconst ASSISTANT_STEP_SELECTOR = \"[data-chat-flow-kind='assistant-step']\"\nconst MARKDOWN_CONTAINER_SELECTOR = \"div[class*='markdown']\"\nconst EXPANDED_HORIZONTAL_CHROME = 96\nconst EXPANDED_MIN_WIDTH = 560\nconst LIGHTBOX_EDGE_GAP = 56\n\ninterface AttributeLease {\n  originalValue: string | null\n  owners: Set<symbol>\n}\n\ninterface ControlLease {\n  button: HTMLButtonElement\n  owners: Map<symbol, () => void>\n  onClick: (event: MouseEvent) => void\n}\n\nconst attributeLeases = new WeakMap<HTMLElement, Map<string, AttributeLease>>()\nconst controlLeases = new WeakMap<HTMLElement, ControlLease>()\n\nfunction setLeasedAttribute(element: HTMLElement, attribute: string, owner: symbol, active: boolean): void {\n  let attributes = attributeLeases.get(element)\n  let lease = attributes?.get(attribute)\n  if (active) {\n    if (attributes === undefined) {\n      attributes = new Map()\n      attributeLeases.set(element, attributes)\n    }\n    if (lease === undefined) {\n      lease = { originalValue: element.getAttribute(attribute), owners: new Set() }\n      attributes.set(attribute, lease)\n    }\n    lease.owners.add(owner)\n    element.setAttribute(attribute, '')\n    return\n  }\n  if (lease === undefined || attributes === undefined) return\n  lease.owners.delete(owner)\n  if (lease.owners.size > 0) {\n    element.setAttribute(attribute, '')\n    return\n  }\n  if (element.getAttribute(attribute) === '') {\n    if (lease.originalValue === null) element.removeAttribute(attribute)\n    else element.setAttribute(attribute, lease.originalValue)\n  }\n  attributes.delete(attribute)\n  if (attributes.size === 0) attributeLeases.delete(element)\n}\n\n/** Labels follow the host language at the moment each control is created. */\nfunction tableLabel(zh: string, en: string): string {\n  return (document.documentElement.lang || navigator.language || 'en').toLowerCase().startsWith('zh') ? zh : en\n}\n\nfunction acquireControl(wrapper: HTMLElement, owner: symbol, activate: () => void): HTMLButtonElement {\n  let lease = controlLeases.get(wrapper)\n  if (lease === undefined) {\n    const button = document.createElement('button')\n    button.type = 'button'\n    button.setAttribute(CONTROL_ATTRIBUTE, '')\n    button.dataset.skinOwner = SKIN_OWNER\n    button.setAttribute('aria-label', tableLabel('展开表格预览', 'Expand table preview'))\n    button.title = button.getAttribute('aria-label')!\n    const owners = new Map<symbol, () => void>()\n    const onClick = (event: MouseEvent): void => {\n      if (!wrapper.hasAttribute(EXPANDABLE_ATTRIBUTE)) return\n      const current = Array.from(owners.values()).at(-1)\n      if (current === undefined) return\n      event.stopPropagation()\n      current()\n    }\n    button.addEventListener('click', onClick)\n    lease = { button, owners, onClick }\n    controlLeases.set(wrapper, lease)\n  }\n  lease.owners.set(owner, activate)\n  try {\n    if (lease.button.parentElement !== wrapper) wrapper.append(lease.button)\n  } catch (error) {\n    releaseControl(wrapper, owner)\n    throw error\n  }\n  return lease.button\n}\n\nfunction releaseControl(wrapper: HTMLElement, owner: symbol): void {\n  const lease = controlLeases.get(wrapper)\n  if (lease === undefined) return\n  lease.owners.delete(owner)\n  if (lease.owners.size > 0) return\n  lease.button.removeEventListener('click', lease.onClick)\n  lease.button.remove()\n  controlLeases.delete(wrapper)\n}\n\ninterface TableCardRuntime {\n  dispose(): void\n}\n\ninterface TableBinding {\n  button: HTMLButtonElement\n  onPointerLeave: () => void\n  onScroll: () => void\n}\n\ninterface TableCandidate {\n  bubble: HTMLElement | null\n  table: HTMLElement | null | undefined\n  availableWidth: number\n  naturalWidth: number\n}\n\ninterface OverlayState {\n  root: HTMLDivElement\n  source: HTMLElement\n  onClick: (event: MouseEvent) => void\n  onKeyDown: (event: KeyboardEvent) => void\n}\n\nfunction isForeignModalDialog(element: Element): boolean {\n  return element.matches(MODAL_DIALOG_SELECTOR)\n    && !element.hasAttribute(OVERLAY_ATTRIBUTE)\n    && element.closest(`[${OVERLAY_ATTRIBUTE}]`) === null\n}\n\nfunction findBubble(wrapper: HTMLElement): HTMLElement | null {\n  const assistantStep = wrapper.closest<HTMLElement>(ASSISTANT_STEP_SELECTOR)\n  const markdown = wrapper.closest<HTMLElement>(MARKDOWN_CONTAINER_SELECTOR)\n  if (assistantStep !== null && markdown !== null && assistantStep.contains(markdown)) return markdown\n  return wrapper.parentElement\n}\n\nfunction contentWidth(element: HTMLElement | null): number {\n  if (element === null || element.clientWidth <= 0) return 0\n  const style = getComputedStyle(element)\n  const start = Number.parseFloat(style.paddingLeft) || 0\n  const end = Number.parseFloat(style.paddingRight) || 0\n  return Math.max(0, element.clientWidth - start - end)\n}\n\nfunction contentInlineSize(entry: ResizeObserverEntry): number {\n  return entry.contentBoxSize?.[0]?.inlineSize ?? entry.contentRect.width\n}\n\nfunction borderInlineSize(entry: ResizeObserverEntry): number {\n  return entry.borderBoxSize?.[0]?.inlineSize ?? entry.contentRect.width\n}\n\n/**\n * Install the wide-table geometry pass on the current body. Idempotent per\n * call; every observer and mutation is torn down by the returned disposer.\n */\nexport function installMaidTableCards(_ctx: Context): TableCardRuntime {\n  const owner = Symbol('maid-table-card-activation')\n  const bindings = new Map<HTMLElement, TableBinding>()\n  const candidates = new Map<HTMLElement, TableCandidate>()\n  const resizeTargets = new Map<Element, Set<HTMLElement>>()\n  let observer: MutationObserver | undefined\n  let resizeObserver: ResizeObserver | undefined\n  let overlay: OverlayState | undefined\n  const closingOverlays = new Map<HTMLDivElement, ReturnType<typeof setTimeout>>()\n\n  const closeOverlay = (immediate = false): void => {\n    if (overlay === undefined) return\n    const { root, source, onClick, onKeyDown } = overlay\n    overlay = undefined\n    setLeasedAttribute(source, OPEN_ATTRIBUTE, owner, false)\n    root.removeEventListener('click', onClick)\n    document.removeEventListener('keydown', onKeyDown)\n    if (immediate) {\n      root.remove()\n      return\n    }\n    root.dataset.maidTableClosing = ''\n    const timer = window.setTimeout(() => {\n      closingOverlays.delete(root)\n      root.remove()\n    }, 180)\n    closingOverlays.set(root, timer)\n  }\n\n  const deactivate = (wr